INSERT INTO "wa_outreach" (id, lead_id, message_template, message_text, sent_at, sent_by, status, response_text, response_at, follow_up_needed, created_at) VALUES (1, 'KIMI-147', 'The Observer', 'Halo Bapak/Ibu. Kami dari Indibiz Telkom Area Jakarta Pusat. Kami sering lewat area Gajah Mada–Hayam Wuruk–Harmoni dan notice banyak bisnis masih pakai koneksi rumahan untuk operasional. Padahal untuk bisnis, ada layanan khusus dengan dukungan teknis 24 jam dan jaminan lebih stabil. Bisa kami cek apakah Hotel Gren Alia Jakarta sudah pakai layanan bisnis atau masih layanan rumahan? Gratis, nggak ada kewajiban. 🙏', NULL, 'system', 'draft', NULL, NULL, 0, '2026-05-05 09:26:50');
INSERT INTO "wa_outreach" (id, lead_id, message_template, message_text, sent_at, sent_by, status, response_text, response_at, follow_up_needed, created_at) VALUES (2, 'KIMI-147', 'The Insider', 'Halo Bapak/Ibu. Kami dari Indibiz Telkom Area Jakarta Pusat. Bulan ini ada program pemasangan baru untuk bisnis di area Gajah Mada–Hayam Wuruk–Harmoni dengan biaya pasang lebih ringan. Paket internet bisnis mulai Rp320rb/bulan, unlimited tanpa batasan. Kalau Hotel Gren Alia Jakarta tertarik cek ketersediaan, bisa reply WA ini. 🙏', NULL, 'system', 'draft', NULL, NULL, 0, '2026-05-05 09:26:58');
INSERT INTO "wa_outreach" (id, lead_id, message_template, message_text, sent_at, sent_by, status, response_text, response_at, follow_up_needed, created_at) VALUES (3, 'KIMI-147', 'The Problem Solver', 'Halo Bapak/Ibu. Kami dari Indibiz Telkom Area Jakarta Pusat. Untuk bisnis di area Gajah Mada–Hayam Wuruk–Harmoni, koneksi stabil penting buat kelancaran transaksi harian — terutama yang pakai QRIS atau order online. Indibiz pakai fiber dengan upload-download 1:1, jadi upload juga kencang. Bisa kami bantu cek jaringan di lokasi Hotel Gren Alia Jakarta? 🙏', NULL, 'system', 'draft', NULL, NULL, 0, '2026-05-05 09:27:08');
INSERT INTO "wa_outreach" (id, lead_id, message_template, message_text, sent_at, sent_by, status, response_text, response_at, follow_up_needed, created_at) VALUES (4, 'KIMI-147', 'The Social Proof', 'Halo Bapak/Ibu. Kami dari Indibiz Telkom Area Jakarta Pusat. Beberapa bisnis di sekitar Gajah Mada–Hayam Wuruk–Harmoni yang kami bantu bulan lalu merasa lebih tenang operasionalnya setelah pakai koneksi khusus bisnis. Kalau Hotel Gren Alia Jakarta mau lihat perbandingan paket, saya bisa kirim via WA. 🙏', NULL, 'system', 'draft', NULL, NULL, 0, '2026-05-05 09:27:14');
INSERT INTO "wa_outreach" (id, lead_id, message_template, message_text, sent_at, sent_by, status, response_text, response_at, follow_up_needed, created_at) VALUES (5, 'KIMI-147', 'The Minimalist', 'Halo Bapak/Ibu. Kami dari Indibiz Telkom Area Jakarta Pusat. Kami punya layanan internet khusus bisnis di area Gajah Mada–Hayam Wuruk–Harmoni, mulai Rp320rb/bulan unlimited. Mau saya kirimkan detail paketnya? 🙏', NULL, 'system', 'draft', NULL, NULL, 0, '2026-05-05 09:27:20');
INSERT INTO "wa_outreach" (id, lead_id, message_template, message_text, sent_at, sent_by, status, response_text, response_at, follow_up_needed, created_at) VALUES (6, 'KIMI-147', 'F&B Specific', 'Halo Bapak/Ibu. Kami dari Indibiz Telkom Area Jakarta Pusat. Untuk resto/cafe di area Gajah Mada–Hayam Wuruk–Harmoni, koneksi stabil itu penting — QRIS, order online, dan komunikasi dengan driver ojek. Indibiz pakai fiber dengan upload-download 1:1, jadi semua lancar. Bisa kami cek jaringan di Hotel Gren Alia Jakarta? 🙏', NULL, 'system', 'draft', NULL, NULL, 0, '2026-05-05 09:27:25');
INSERT INTO "wa_outreach" (id, lead_id, message_template, message_text, sent_at, sent_by, status, response_text, response_at, follow_up_needed, created_at) VALUES (7, 'KIMI-147', 'Kantor/Professional', 'Halo Bapak/Ibu. Kami dari Indibiz Telkom Area Jakarta Pusat. Untuk kantor di area Gajah Mada–Hayam Wuruk–Harmoni, koneksi bisnis dengan SLA lebih cepat dan upload-download 1:1 itu penting — terutama buat video call dan kirim file besar. Bisa kami cek ketersediaan jaringan untuk Hotel Gren Alia Jakarta? 🙏', NULL, 'system', 'draft', NULL, NULL, 0, '2026-05-05 09:27:28');
INSERT INTO "wa_outreach" (id, lead_id, message_template, message_text, sent_at, sent_by, status, response_text, response_at, follow_up_needed, created_at) VALUES (8, 'KIMI-147', 'Migration', 'Halo Bapak/Ibu. Kami dari Indibiz Telkom Area Jakarta Pusat. Kami lihat Hotel Gren Alia Jakarta sudah terpasang internet. Kalau ada keluhan lambat atau biaya bulanan naik, Indibiz punya paket khusus bisnis unlimited tanpa FUP dengan upload-download 1:1. Bisa kami bantu bandingkan paket saat ini? 🙏', NULL, 'system', 'draft', NULL, NULL, 0, '2026-05-05 09:27:31');
INSERT INTO "wa_outreach" (id, lead_id, message_template, message_text, sent_at, sent_by, status, response_text, response_at, follow_up_needed, created_at) VALUES (9, 'KIMI-034', 'Migration', 'Halo Bapak/Ibu. Kami dari Indibiz Telkom Area Jakarta Pusat. Kami lihat PT Nusantara Berlian Motor (Mitsubishi Suryopranoto) sudah terpasang internet. Kalau ada keluhan lambat atau biaya bulanan naik, Indibiz punya paket khusus bisnis unlimited tanpa FUP dengan upload-download 1:1. Bisa kami bantu bandingkan paket saat ini? 🙏', NULL, 'system', 'draft', NULL, NULL, 0, '2026-05-05 09:27:42');
