-- TABLES
CREATE TABLE agents (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      phone TEXT,
      role TEXT DEFAULT 'field_agent',
      active INTEGER DEFAULT 1,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP
    );

CREATE TABLE leads (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      lead_id TEXT UNIQUE,
      business_name TEXT NOT NULL,
      segment TEXT,
      cluster TEXT,
      kelurahan TEXT,
      address TEXT,
      lat REAL,
      lng REAL,
      phone_primary TEXT,
      phone_all TEXT,
      email TEXT,
      preferred_channel TEXT,
      current_provider TEXT,
      pain_point TEXT,
      sales_signal TEXT,
      pipeline_stage TEXT DEFAULT 'Not Contacted',
      product_offered TEXT,
      est_mrc TEXT,
      probability REAL DEFAULT 0,
      priority_score REAL DEFAULT 0,
      pre_visit_priority TEXT,
      next_action TEXT,
      next_action_date TEXT,
      pic_owner TEXT,
      internal_notes TEXT,
      desk_notes TEXT,
      source_url TEXT,
      discovery_keyword TEXT,
      import_batch TEXT,
      visit_status INTEGER DEFAULT 0,
      claimed_by TEXT,
      claimed_at TEXT,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    );

CREATE TABLE sales_queue (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      lead_id TEXT NOT NULL,
      sales_motion TEXT,
      recommended_product TEXT,
      recommended_pitch TEXT,
      channel TEXT,
      priority_reason TEXT,
      deadline TEXT,
      assigned_to TEXT,
      status TEXT DEFAULT 'open',
      completed_at TEXT,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (lead_id) REFERENCES leads(lead_id)
    );

CREATE TABLE sqlite_sequence(name,seq);

CREATE TABLE status_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      lead_id TEXT NOT NULL,
      old_status TEXT,
      new_status TEXT,
      changed_by TEXT,
      changed_at TEXT DEFAULT CURRENT_TIMESTAMP,
      reason TEXT,
      FOREIGN KEY (lead_id) REFERENCES leads(lead_id)
    );

CREATE TABLE visits (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      lead_id TEXT NOT NULL,
      agent_name TEXT,
      visit_date TEXT,
      visit_time TEXT,
      outcome TEXT,
      provider_identified TEXT,
      contact_captured TEXT,
      contact_name TEXT,
      contact_role TEXT,
      pain_noted TEXT,
      next_action TEXT,
      next_action_date TEXT,
      notes TEXT,
      gps_lat REAL,
      gps_lng REAL,
      photo_path TEXT,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (lead_id) REFERENCES leads(lead_id)
    );

CREATE TABLE wa_outreach (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      lead_id TEXT NOT NULL,
      message_template TEXT,
      message_text TEXT,
      sent_at TEXT,
      sent_by TEXT,
      status TEXT DEFAULT 'draft', -- draft, sent, delivered, read, replied, no_response
      response_text TEXT,
      response_at TEXT,
      follow_up_needed INTEGER DEFAULT 0,
      created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (lead_id) REFERENCES leads(lead_id)
    );

